using NUnit.Framework;
using QFramework;
using UnityEngine;
namespace BeeHarvest.Tests {
 public sealed class HiddenTargetRecoveryTests:EconomyTestFixture {
  static LevelData Board(bool alternative=true,bool reuseSlot=false){var data=new LevelData{cubes=alternative?new[]{new CubeData{id=0,x=0,y=0,z=0,color="Red"},new CubeData{id=1,x=0,y=0,z=1,color="Yellow"},new CubeData{id=2,x=2,y=0,z=1,color="Red"},new CubeData{id=3,x=3,y=0,z=1,color="Yellow"},new CubeData{id=4,x=4,y=0,z=1,color="Yellow"}}:new[]{new CubeData{id=0,x=0,y=0,z=0,color="Red"},new CubeData{id=1,x=0,y=0,z=1,color="Yellow"}},hives=alternative?(reuseSlot?new[]{new HiveData{column=0,color="Red",quota=1},new HiveData{column=1,color="Yellow",quota=3},new HiveData{column=2,color="Red",quota=1}}:new[]{new HiveData{column=0,color="Red",quota=2},new HiveData{column=1,color="Yellow",quota=3}}):new[]{new HiveData{column=0,color="Red",quota=1},new HiveData{column=1,color="Yellow",quota=1}}};if(reuseSlot){data.cubes=new[]{data.cubes[0],data.cubes[1],data.cubes[2],data.cubes[3],data.cubes[4],new CubeData{id=5,x=5,y=0,z=1,color="Yellow"}};data.hives[1].quota=4;}return data;}
  [Test] public void CommittedTargetStaysTheSameEvenWhenAnotherVisibleBlockCouldReplaceIt(){
   var app=BeeHarvestApp.Interface;app.SendCommand(new StartLevelCommand(Board()));app.SendCommand(new ActivateHiveCommand(0));var m=app.GetModel<HarvestModel>();var f=m.Flights[0];Assert.AreEqual(0,f.Cube);
   app.SendCommand(new AdvanceHarvestCommand(.25f));app.SendCommand(new UpdateHarvestViewCommand(Vector3.forward,new Vector3(0,0,100)));Assert.AreEqual(1,m.Cubes[2].Stage,"The second bee can reserve the visible alternative independently");app.SendCommand(new AdvanceHarvestCommand(.4f));
   Assert.AreEqual(0,f.Cube,"The departed bee must keep its reserved block even after it rotates out of view");Assert.AreEqual(.65f,f.Progress,.00001f);Assert.AreEqual(f.Id,m.Cubes[0].Task);Assert.AreEqual(1,m.Cubes[0].Stage);Assert.AreEqual(2,m.Flights.Count,"Another reservation does not replace the first bee target");
   app.SendCommand(new AdvanceHarvestCommand(AdvanceHarvestCommand.OutboundSeconds-.65f+.01f));Assert.AreEqual(1,f.Stage);Assert.AreEqual(2,m.Cubes[0].Stage);for(int i=0;i<200&&m.Deposited<2;i++)app.SendCommand(new AdvanceHarvestCommand(.1f));Assert.AreEqual(2,m.Deposited);Assert.AreEqual(0,m.InTransit);Assert.AreEqual(0,m.Hives[0].Remaining);Assert.AreEqual(0,m.Hives[0].Reserved);Assert.AreEqual(0,m.Hives[0].Busy);Assert.AreEqual(5,m.Remaining+m.InTransit+m.Deposited);
  }
  [Test] public void NoVisibleReplacementDoesNotStopTheCommittedBlockAndPauseAndSpeedStillApply(){
   var app=BeeHarvestApp.Interface;app.SendCommand(new StartLevelCommand(Board(false)));app.SendCommand(new ActivateHiveCommand(0));var m=app.GetModel<HarvestModel>();var f=m.Flights[0];app.SendCommand(new AdvanceHarvestCommand(AdvanceHarvestCommand.OutboundSeconds-.15f));app.SendCommand(new PauseHarvestCommand(true));app.SendCommand(new UpdateHarvestViewCommand(Vector3.forward,new Vector3(0,0,100)));Assert.IsFalse(app.GetSystem<HarvestSystem>().IsCameraVisible(f.Cube));Assert.AreEqual(-1,app.GetSystem<HarvestSystem>().FindTarget("Red"));app.SendCommand(new AdvanceHarvestCommand(3));Assert.AreEqual(AdvanceHarvestCommand.OutboundSeconds-.15f,f.Progress,.00001f);
   app.SendCommand(new PauseHarvestCommand(false));app.SendCommand(new RefillHarvestBoosterCommand(1));app.SendCommand(new UseHarvestSpeedCommand());app.SendCommand(new AdvanceHarvestCommand(.1f));Assert.AreEqual(1,f.Stage,"A hidden committed block still crosses pickup normally");Assert.AreEqual(0,f.Cube);Assert.AreEqual(1,m.InTransit);Assert.AreEqual(0,m.Hives[0].Reserved);app.SendCommand(new AdvanceHarvestCommand(AdvanceHarvestCommand.LoadedSeconds*.5f+.01f));Assert.AreEqual(2,f.Stage);Assert.AreEqual(1,m.Deposited);Assert.AreEqual(0,m.InTransit);Assert.AreEqual(0,m.Hives[0].Busy);Assert.AreEqual(2,m.Remaining+m.InTransit+m.Deposited);
  }
  [Test] public void HiddenCommittedPickupDoesNotReclaimTheHivesReusedSlot(){
   var app=BeeHarvestApp.Interface;app.SendCommand(new StartLevelCommand(Board(true,true)));app.SendCommand(new ActivateHiveCommand(0));var m=app.GetModel<HarvestModel>();Assert.AreEqual(-1,m.Hives[0].Slot);app.SendCommand(new ActivateHiveCommand(1));Assert.AreEqual(1,m.Slots[0]);app.SendCommand(new UpdateHarvestViewCommand(Vector3.forward,new Vector3(0,0,100)));app.SendCommand(new AdvanceHarvestCommand(.7f));var f=m.Flights[0];Assert.AreEqual(0,f.Cube);Assert.AreEqual(.7f,f.Progress,.00001f);Assert.AreEqual(1,m.Slots[0]);Assert.AreEqual(-1,m.Hives[0].Slot);app.SendCommand(new AdvanceHarvestCommand(AdvanceHarvestCommand.OutboundSeconds-.7f+.01f));Assert.AreEqual(1,f.Stage);Assert.AreEqual(1,m.Slots[0]);Assert.AreEqual(0,m.Hives[0].Remaining);Assert.AreEqual(0,m.Hives[0].Reserved);Assert.AreEqual(1,m.Hives[0].Busy);
  }
 }
}
